#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_inplace_scatter_add.h"

namespace ascend_kernel {

constexpr int64_t MAX_CORES = 40;
constexpr int64_t MAX_INDEX_BATCH = 512;
constexpr int64_t UB_ALIGN_BYTES = 32;
constexpr int64_t SYSTEM_WORKSPACE_SIZE = 16 * 1024 * 1024;  // 16MB

at::Tensor inplace_scatter_add(
    const at::Tensor &var,
    const at::Tensor &indices,
    const at::Tensor &updates)
{
    // ---- 输入校验 ----
    TORCH_CHECK(var.device().type() == c10::DeviceType::PrivateUse1,
                "inplace_scatter_add: var must be on NPU device");
    TORCH_CHECK(indices.device().type() == c10::DeviceType::PrivateUse1,
                "inplace_scatter_add: indices must be on NPU device");
    TORCH_CHECK(updates.device().type() == c10::DeviceType::PrivateUse1,
                "inplace_scatter_add: updates must be on NPU device");

    TORCH_CHECK(var.dim() == 2, "inplace_scatter_add: var must be 2D [M, N], got ", var.dim());
    TORCH_CHECK(indices.dim() == 1, "inplace_scatter_add: indices must be 1D [K], got ", indices.dim());
    TORCH_CHECK(updates.dim() == 2, "inplace_scatter_add: updates must be 2D [K, N], got ", updates.dim());

    auto varScalarType = var.scalar_type();
    TORCH_CHECK(varScalarType == at::kFloat || varScalarType == at::kInt ||
                varScalarType == at::kHalf,
                "inplace_scatter_add: var dtype must be float32, int32 or float16");
    TORCH_CHECK(updates.scalar_type() == varScalarType,
                "inplace_scatter_add: updates dtype must match var dtype");

    // ---- 维度参数 ----
    at::Tensor varContiguous = var.contiguous();
    at::Tensor indicesContiguous = indices.contiguous();
    at::Tensor updatesContiguous = updates.contiguous();

    int64_t M = varContiguous.size(0);
    int64_t N = varContiguous.size(1);
    int64_t K = indicesContiguous.size(0);

    TORCH_CHECK(updatesContiguous.size(0) == K,
                "inplace_scatter_add: updates.size(0) must equal indices.size(0)");
    TORCH_CHECK(updatesContiguous.size(1) == N,
                "inplace_scatter_add: updates.size(1) must equal var.size(1)");

    // ---- dtype 参数 ----
    int64_t dtypeSize = static_cast<int64_t>(varContiguous.element_size());
    int64_t isInt32 = (varScalarType == at::kInt) ? int64_t(1) : int64_t(0);

    // ---- Index 转 int32 ----
    at::Tensor indexInt32;
    if (indicesContiguous.scalar_type() != at::kInt) {
        indexInt32 = indicesContiguous.to(at::kInt);
    } else {
        indexInt32 = indicesContiguous;
    }

    // ---- 创建输出 (clone var) ----
    at::Tensor output = varContiguous.clone();

    // ---- 获取平台硬件参数 ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    (void)coreNum;

    // ---- 对齐参数 ----
    int64_t alignElements = UB_ALIGN_BYTES / dtypeSize;
    int64_t alignedN = ((N + alignElements - 1) / alignElements) * alignElements;

    // ---- Workspace ----
    size_t workspaceSize = SYSTEM_WORKSPACE_SIZE;
    auto workspace = at::empty({static_cast<int64_t>(workspaceSize)},
                               at::TensorOptions().dtype(at::kByte).device(var.device()));

    // ---- 分批 Launch (M > MAX_CORES 时) ----
    int64_t rowOffset = 0;
    while (rowOffset < M) {
        int64_t batchM = M - rowOffset;
        if (batchM > MAX_CORES) {
            batchM = MAX_CORES;
        }

        // 根据 batchM 计算 rowsPerCore (取最大 core 的行数)
        int64_t rowsPerCore = (batchM + MAX_CORES - 1) / MAX_CORES;
        if (rowsPerCore < 1) {
            rowsPerCore = 1;
        }

        // 计算 UB 级 tiling 参数: indexBatchSize
        // varBuf 大小 (用最大可能的 rowsPerCore)
        int64_t varBufBytes = rowsPerCore * alignedN * dtypeSize;

        // indexBatchSize 不能直接使用 ubSize (是 64-bit), 需要赋值给局部变量
        uint64_t ubSizeUint = ubSize;
        int64_t ubSizeInt = static_cast<int64_t>(ubSizeUint);

        // 剩余 UB 用于 index + update buffers
        int64_t remainingUb = ubSizeInt - varBufBytes;
        // 每个 index batch item: 4B (int32) + alignedN * dtypeSize (update row)
        int64_t bytesPerIndexItem = static_cast<int64_t>(sizeof(int32_t)) + alignedN * dtypeSize;
        int64_t maxBatchSize = remainingUb / bytesPerIndexItem;
        if (maxBatchSize < 1) {
            maxBatchSize = 1;
        }

        int64_t indexBatchSize = K;
        if (indexBatchSize > maxBatchSize) {
            indexBatchSize = maxBatchSize;
        }
        if (indexBatchSize > MAX_INDEX_BATCH) {
            indexBatchSize = MAX_INDEX_BATCH;
        }
        if (indexBatchSize < 1) {
            indexBatchSize = 1;
        }

        // 准备 batch 的 var slice (narrow 第 0 维)
        auto varBatch = output.narrow(0, rowOffset, batchM);

        // 全部参数转为左值局部变量
        uint32_t blockDimVal = static_cast<uint32_t>(batchM);
        int64_t batchMLocal = batchM;
        int64_t nLocal = N;
        int64_t kLocal = K;
        int64_t rowOffsetLocal = rowOffset;
        int64_t idxBatchLocal = indexBatchSize;
        int64_t alignedNLocal = alignedN;
        int64_t dtypeSizeLocal = dtypeSize;
        int64_t isInt32Local = isInt32;

        EXEC_KERNEL_CMD(inplace_scatter_add, blockDimVal,
                        varBatch, indexInt32, updatesContiguous,
                        batchMLocal, nLocal, kLocal, rowOffsetLocal,
                        idxBatchLocal, alignedNLocal,
                        dtypeSizeLocal, isInt32Local);

        rowOffset += batchM;
    }

    return output;
}

}  // namespace ascend_kernel
