// ============================================================
// InplaceScatterAdd Kernel
// dim=0 scatter add: result[indices[k], :] += updates[k, :]
// Mode B: 每核独占一组 var 行，核内按 index 批次累加
// 使用 alignedN 确保 UB 内 32B 对齐
// ============================================================

#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t UB_CAPACITY = 192 * 1024;
constexpr int64_t MAX_INDEX_BATCH = 512;
constexpr int64_t MAX_CORES = 40;

template<typename T>
class KernelInplaceScatterAdd {
public:
    __aicore__ inline KernelInplaceScatterAdd() {}
    __aicore__ inline void Init(GM_ADDR var, GM_ADDR index, GM_ADDR updates,
                                 int64_t batchM, int64_t N, int64_t K,
                                 int64_t globalRowOffset,
                                 int64_t indexBatchSize, int64_t alignedN);
    __aicore__ inline void Process();

private:
    TPipe pipe;

    TBuf<TPosition::VECIN> varInBuf_;
    TBuf<TPosition::VECOUT> varOutBuf_;
    TBuf<TPosition::VECIN> indexBuf_;
    TBuf<TPosition::VECIN> updateBuf_;

    GlobalTensor<T> varGm_;
    GlobalTensor<int32_t> indexGm_;
    GlobalTensor<T> updateGm_;

    int64_t batchM_ = 0;
    int64_t N_ = 0;
    int64_t K_ = 0;
    int64_t globalRowOffset_ = 0;
    int64_t indexBatchSize_ = 0;
    int64_t indexBatchCount_ = 0;
    int64_t alignedN_ = 0;

    int64_t myRows_ = 0;
    int64_t myGlobalRowStart_ = 0;
    int64_t myLocalRowStart_ = 0;
};

template<typename T>
__aicore__ inline void KernelInplaceScatterAdd<T>::Init(
    GM_ADDR var, GM_ADDR index, GM_ADDR updates,
    int64_t batchM, int64_t N, int64_t K,
    int64_t globalRowOffset,
    int64_t indexBatchSize, int64_t alignedN)
{
    batchM_ = batchM;
    N_ = N;
    K_ = K;
    globalRowOffset_ = globalRowOffset;
    indexBatchSize_ = indexBatchSize;
    indexBatchCount_ = (K_ + indexBatchSize_ - 1) / indexBatchSize_;
    alignedN_ = alignedN;

    int64_t blockIdx = GetBlockIdx();
    int64_t blockDim = (batchM_ < MAX_CORES) ? batchM_ : MAX_CORES;
    if (blockIdx >= blockDim) {
        myRows_ = 0;
        return;
    }

    int64_t base = batchM_ / blockDim;
    int64_t remainder = batchM_ % blockDim;
    if (blockIdx < remainder) {
        myLocalRowStart_ = blockIdx * (base + 1);
        myRows_ = base + 1;
    } else {
        myLocalRowStart_ = remainder * (base + 1) + (blockIdx - remainder) * base;
        myRows_ = base;
    }
    myGlobalRowStart_ = globalRowOffset_ + myLocalRowStart_;

    if (myRows_ <= 0) return;

    varGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(var), batchM_ * N_);
    indexGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(index));
    updateGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(updates), K_ * N_);

    int64_t varBufBytes = myRows_ * alignedN_ * sizeof(T);
    int64_t indexBufBytes = indexBatchSize_ * sizeof(int32_t);
    // updateBuf: store alignedN_ per row for 32B alignment
    int64_t updateBufBytes = indexBatchSize_ * alignedN_ * sizeof(T);

    pipe.InitBuffer(varInBuf_, varBufBytes);
    pipe.InitBuffer(varOutBuf_, varBufBytes);
    pipe.InitBuffer(indexBuf_, indexBufBytes);
    pipe.InitBuffer(updateBuf_, updateBufBytes);
}

template<typename T>
__aicore__ inline void KernelInplaceScatterAdd<T>::Process()
{
    if (myRows_ <= 0) return;

    // ---- Step 1: 逐行加载 var 到 UB (每行按 alignedN_ 对齐) ----
    LocalTensor<T> varInLocal = varInBuf_.Get<T>();
    {
        DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(N_ * sizeof(T));
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;
        DataCopyPadExtParams<T> padParams;
        padParams.isPad = false;
        for (int64_t r = 0; r < myRows_; r++) {
            DataCopyPad(varInLocal[r * alignedN_],
                        varGm_[(myLocalRowStart_ + r) * N_],
                        copyParams, padParams);
        }
    }
    PipeBarrier<PIPE_ALL>();

    // ---- Step 2: 逐批处理 indices ----
    for (int64_t ib = 0; ib < indexBatchCount_; ib++) {
        int64_t batchStart = ib * indexBatchSize_;
        int64_t batchK = indexBatchSize_;
        if (ib == indexBatchCount_ - 1) {
            batchK = K_ - batchStart;
        }

        // 2a. 加载 index batch (int32, 无需对齐到32B)
        LocalTensor<int32_t> indexLocal = indexBuf_.Get<int32_t>();
        {
            DataCopyExtParams copyParams;
            copyParams.blockCount = 1;
            copyParams.blockLen = static_cast<uint32_t>(batchK * sizeof(int32_t));
            copyParams.srcStride = 0;
            copyParams.dstStride = 0;
            DataCopyPadExtParams<int32_t> padParams;
            padParams.isPad = false;
            DataCopyPad(indexLocal, indexGm_[batchStart], copyParams, padParams);
        }
        PipeBarrier<PIPE_ALL>();

        // 2b. 逐行加载 update batch 到 UB (每行按 alignedN_ 对齐)
        LocalTensor<T> updateLocal = updateBuf_.Get<T>();
        {
            DataCopyExtParams copyParams;
            copyParams.blockCount = 1;
            copyParams.blockLen = static_cast<uint32_t>(N_ * sizeof(T));
            copyParams.srcStride = 0;
            copyParams.dstStride = 0;
            DataCopyPadExtParams<T> padParams;
            padParams.isPad = false;
            for (int64_t k = 0; k < batchK; k++) {
                DataCopyPad(updateLocal[k * alignedN_],
                            updateGm_[(batchStart + k) * N_],
                            copyParams, padParams);
            }
        }
        PipeBarrier<PIPE_ALL>();

        // 2c. 遍历该批次的每个 index，命中则向量累加到对应 var 行
        for (int64_t k = 0; k < batchK; k++) {
            int32_t targetRow = indexLocal.GetValue(k);
            if (targetRow >= myGlobalRowStart_ && targetRow < myGlobalRowStart_ + myRows_) {
                int64_t localRowOff = (targetRow - myGlobalRowStart_) * alignedN_;
                int64_t updateOff = k * alignedN_;
                AscendC::Add(varInLocal[localRowOff], varInLocal[localRowOff],
                             updateLocal[updateOff], static_cast<uint32_t>(N_));
            }
        }
        PipeBarrier<PIPE_ALL>();
    }

    // ---- Step 3: 逐行写回 var 到 GM ----
    LocalTensor<T> varOutLocal = varOutBuf_.Get<T>();
    {
        // 修正: 用逐行 UB→UB DataCopy 确保对齐
        uint32_t copyCount = static_cast<uint32_t>(myRows_ * alignedN_);
        DataCopy(varOutLocal, varInLocal, copyCount);
    }
    PipeBarrier<PIPE_ALL>();

    {
        DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(N_ * sizeof(T));
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;
        for (int64_t r = 0; r < myRows_; r++) {
            DataCopyPad(varGm_[(myLocalRowStart_ + r) * N_],
                        varOutLocal[r * alignedN_],
                        copyParams);
        }
    }
    PipeBarrier<PIPE_ALL>();
}

// =========================== Kernel 入口 ============================

extern "C" __global__ __aicore__ void inplace_scatter_add(
    GM_ADDR var, GM_ADDR index, GM_ADDR updates,
    int64_t batchM, int64_t N, int64_t K,
    int64_t globalRowOffset,
    int64_t indexBatchSize, int64_t alignedN,
    int64_t dtypeSize, int64_t isInt32)
{
    if (isInt32) {
        KernelInplaceScatterAdd<int32_t> op;
        op.Init(var, index, updates, batchM, N, K, globalRowOffset, indexBatchSize, alignedN);
        op.Process();
    } else if (dtypeSize == 4) {
        KernelInplaceScatterAdd<float> op;
        op.Init(var, index, updates, batchM, N, K, globalRowOffset, indexBatchSize, alignedN);
        op.Process();
    } else if (dtypeSize == 2) {
        KernelInplaceScatterAdd<half> op;
        op.Init(var, index, updates, batchM, N, K, globalRowOffset, indexBatchSize, alignedN);
        op.Process();
    }
}
